from datetime import datetime

class ProductService:
    """
    ProductService managed product lifecycle and inventory logic.
    Used for testing automated AI test generation for Python.
    """
    def __init__(self):
        self.products = {}
        # Simple categories for validation
        self.categories = ["ELECTRONICS", "BOOKS", "CLOTHING", "HOME", "BEAUTY"]

    def add_product(self, name, category, price, stock):
        if not name or len(name) < 2:
            raise ValueError("Invalid product name")

        category = category.upper()
        if category not in self.categories:
            raise ValueError(f"Category {category} not supported")

        if price <= 0:
            raise ValueError("Price must be greater than zero")

        if stock < 0:
            raise ValueError("Stock cannot be negative")

        product_id = str(uuid.uuid4())[:8]
        product = {
            "id": product_id,
            "name": name,
            "category": category,
            "price": float(price),
            "stock": int(stock),
            "created_at": datetime.now().isoformat()
        }

        self.products[product_id] = product
        return product

    def update_stock(self, product_id, quantity):
        if product_id not in self.products:
            return False

        new_stock = self.products[product_id]["stock"] + quantity
        if new_stock < 0:
            return False

        self.products[product_id]["stock"] = new_stock
        return True

    def calculate_bulk_price(self, product_id, quantity):
        if product_id not in self.products:
            return -1

        price = self.products[product_id]["price"]
        # Apply volume discounts
        if quantity >= 100:
            discount = 0.20 # 20% off
        elif quantity >= 50:
            discount = 0.10 # 10% off
        elif quantity >= 10:
            discount = 0.05 # 5% off
        else:
            discount = 0

        return (price * quantity) * (1 - discount)

    def find_products_by_category(self, category):
        category = category.upper()
        return [p for p in self.products.values() if p["category"] == category]

    def get_inventory_worth(self):
        return sum(p["price"] * p["stock"] for p in self.products.values())

    def apply_seasonal_discount(self, category, percentage):
        if percentage < 0 or percentage > 100:
            return False

        category = category.upper()
        affected_count = 0
        for p in self.products.values():
            if p["category"] == category:
                p["price"] *= (1 - (percentage / 100))
                affected_count += 1
        return affected_count

class OrderProcessor:
    def __init__(self, tax_rate=0.1, discount_threshold=1000):
        self.tax_rate = tax_rate
        self.discount_threshold = discount_threshold

    def calculate_total(self, items):
        """
        items: list of dicts -> {"name": str, "price": float, "qty": int}
        """
        if not isinstance(items, list) or len(items) == 0:
            raise ValueError("Items must be a non-empty list")

        subtotal = 0

        for item in items:
            if "price" not in item or "qty" not in item:
                raise KeyError("Missing required fields")

            if item["price"] < 0 or item["qty"] <= 0:
                raise ValueError("Invalid price or quantity")

            subtotal += item["price"] * item["qty"]

        discount = self.apply_discount(subtotal)
        tax = self.calculate_tax(subtotal - discount)

        total = subtotal - discount + tax
        return round(total, 2)

    def apply_discount(self, amount):
        if amount > self.discount_threshold:
            return amount * 0.1
        elif amount > 500:
            return amount * 0.05
        return 0

    def calculate_tax(self, amount):
        if amount < 0:
            raise ValueError("Amount cannot be negative")
        return amount * self.tax_rate

    def generate_invoice(self, items):
        total = self.calculate_total(items)
        return {
            "item_count": sum(item["qty"] for item in items),
            "total_amount": total,
            "status": "PAID" if total > 0 else "FREE"
        }


def main():
    processor = OrderProcessor()

    sample_items = [
        {"name": "Laptop", "price": 700, "qty": 1},
        {"name": "Mouse", "price": 50, "qty": 2}
    ]

    invoice = processor.generate_invoice(sample_items)
    print("Invoice:", invoice)


if __name__ == "__main__":
    main()

class UserValidator:
    def __init__(self, min_age=18):
        self.min_age = min_age

    def validate_user(self, user):
        """
        user: dict -> {"name": str, "email": str, "age": int}
        """
        if not isinstance(user, dict):
            raise TypeError("User must be a dictionary")

        required_fields = ["name", "email", "age"]
        for field in required_fields:
            if field not in user:
                raise KeyError(f"Missing field: {field}")

        if not user["name"] or len(user["name"]) < 3:
            raise ValueError("Invalid name")

        if not self._is_valid_email(user["email"]):
            raise ValueError("Invalid email")

        if not isinstance(user["age"], int):
            raise TypeError("Age must be an integer")

        if user["age"] < 0:
            raise ValueError("Age cannot be negative")

        if user["age"] < self.min_age:
            return "UNDERAGE"

        return "VALID"

    def _is_valid_email(self, email):
        if not isinstance(email, str) or "@" not in email:
            return False

        parts = email.split("@")
        if len(parts) != 2:
            return False

        domain = parts[1]
        if "." not in domain:
            return False

        return True

    def generate_username(self, name, age):
        if not name or not isinstance(age, int):
            raise ValueError("Invalid input")

        base = name.strip().lower().replace(" ", "")
        return f"{base}{age}"


def main():
    validator = UserValidator()

    sample_user = {
        "name": "Sahil Naik",
        "email": "sahil@example.com",
        "age": 22
    }

    status = validator.validate_user(sample_user)
    username = validator.generate_username(sample_user["name"], sample_user["age"])

    print("Status:", status)
    print("Username:", username)


if __name__ == "__main__":
    main()

class LoginManager:
    def __init__(self, max_attempts=3):
        self.users = {}  # username -> password
        self.failed_attempts = {}  # username -> count
        self.locked_users = set()
        self.max_attempts = max_attempts

    def register_user(self, username, password):
        if not username or not password:
            raise ValueError("Username and password required")

        if username in self.users:
            raise ValueError("User already exists")

        if len(password) < 6:
            raise ValueError("Password too short")

        self.users[username] = password
        self.failed_attempts[username] = 0

    def login(self, username, password):
        if username in self.locked_users:
            return "LOCKED"

        if username not in self.users:
            raise KeyError("User not found")

        if self.users[username] == password:
            self.failed_attempts[username] = 0
            return "SUCCESS"

        self.failed_attempts[username] += 1

        if self.failed_attempts[username] >= self.max_attempts:
            self.locked_users.add(username)
            return "LOCKED"

        return "FAILED"

    def reset_password(self, username, new_password):
        if username not in self.users:
            raise KeyError("User not found")

        if len(new_password) < 6:
            raise ValueError("Password too short")

        self.users[username] = new_password
        self.failed_attempts[username] = 0
        if username in self.locked_users:
            self.locked_users.remove(username)

    def get_status(self, username):
        if username in self.locked_users:
            return "LOCKED"
        if username in self.users:
            return "ACTIVE"
        return "NOT_FOUND"


def main():
    manager = LoginManager()

    manager.register_user("sahil", "password123")

    print(manager.login("sahil", "wrong"))
    print(manager.login("sahil", "wrong"))
    print(manager.login("sahil", "wrong"))  # should lock

    print(manager.get_status("sahil"))

    manager.reset_password("sahil", "newpass123")
    print(manager.login("sahil", "newpass123"))


if __name__ == "__main__":
    main()

class TaskScheduler:
    def __init__(self):
        self.tasks = []  # list of dicts
#dev
    def add_task(self, task):
        """
        task: {"title": str, "priority": int, "duration": int}
        """
        if not isinstance(task, dict):
            raise TypeError("Task must be a dictionary")

        required_fields = ["title", "priority", "duration"]
        for field in required_fields:
            if field not in task:
                raise KeyError(f"Missing field: {field}")

        if not task["title"]:
            raise ValueError("Title cannot be empty")

        if not isinstance(task["priority"], int) or not (1 <= task["priority"] <= 5):
            raise ValueError("Priority must be between 1 and 5")

        if not isinstance(task["duration"], int) or task["duration"] <= 0:
            raise ValueError("Duration must be positive")

        self.tasks.append(task)

    def get_schedule(self):
        """
        Returns tasks sorted by priority (higher first)
        """
        return sorted(self.tasks, key=lambda x: -x["priority"])

    def get_total_duration(self):
        total = sum(task["duration"] for task in self.tasks)
        return total

    def find_task(self, title):
        for task in self.tasks:
            if task["title"] == title:
                return task
        return None

    def remove_task(self, title):
        for i, task in enumerate(self.tasks):
            if task["title"] == title:
                del self.tasks[i]
                return True
        return False


def main():
    scheduler = TaskScheduler()

    scheduler.add_task({"title": "Code Review", "priority": 5, "duration": 2})
    scheduler.add_task({"title": "Write Tests", "priority": 4, "duration": 3})
    scheduler.add_task({"title": "Fix Bugs", "priority": 5, "duration": 4})

    print("Schedule:", scheduler.get_schedule())
    print("Total Duration:", scheduler.get_total_duration())

    print("Find Task:", scheduler.find_task("Write Tests"))

    scheduler.remove_task("Code Review")
    print("Updated Schedule:", scheduler.get_schedule())


if __name__ == "__main__":
    main()

